        semantic.sort_by(|(left_index, _, left), (right_index, _, right)| {
            left.cmp_precedence(right)
                .then_with(|| left_index.cmp(right_index))
        });
        opaque.extend(semantic.into_iter().map(|(_, value, _)| value));
